
-- Contoso Industrial service claim system
-- Generated by scenario/build/gen_db.py - do not edit by hand.
-- Dialect: sqlite

DROP TABLE IF EXISTS ClaimAdjudicationDraft;
DROP TABLE IF EXISTS EvidenceRequest;
DROP TABLE IF EXISTS GoodwillEscalation;
DROP TABLE IF EXISTS TsbApplicability;
DROP TABLE IF EXISTS GoodwillAuthority;
DROP TABLE IF EXISTS ServiceHistory;
DROP TABLE IF EXISTS AssetTelemetry;
DROP TABLE IF EXISTS Claims;
DROP TABLE IF EXISTS Assets;
DROP TABLE IF EXISTS Parts;
DROP TABLE IF EXISTS Dealers;

CREATE TABLE Dealers (
    dealer_id            TEXT PRIMARY KEY,
    name                 TEXT NOT NULL,
    region               TEXT NOT NULL,
    currency             TEXT NOT NULL,
    uplift_pct           REAL NOT NULL,
    agreement_ref        TEXT NOT NULL,
    submission_sla_days  INTEGER NOT NULL
);

CREATE TABLE Parts (
    part_no        TEXT PRIMARY KEY,
    description    TEXT NOT NULL,
    family         TEXT NOT NULL,
    component      TEXT,
    supersedes     TEXT,
    superseded_by  TEXT,
    price_inr      REAL,
    price_eur      REAL,
    price_sgd      REAL
);

CREATE TABLE Assets (
    serial              TEXT PRIMARY KEY,
    family              TEXT NOT NULL,
    dealer_id           TEXT NOT NULL REFERENCES Dealers(dealer_id),
    customer_id         TEXT,
    customer_name       TEXT,
    site                TEXT,
    region              TEXT NOT NULL,
    install_date        TEXT,
    -- NULL for a small number of assets. Policy 2.3: coverage cannot be
    -- determined and install_date must not be substituted.
    commissioning_date  TEXT
);

CREATE TABLE AssetTelemetry (
    serial         TEXT NOT NULL REFERENCES Assets(serial),
    as_of_date     TEXT NOT NULL,
    running_hours  INTEGER NOT NULL,
    PRIMARY KEY (serial, as_of_date)
);

CREATE TABLE Claims (
    claim_id              TEXT PRIMARY KEY,
    serial                TEXT NOT NULL,
    dealer_id             TEXT NOT NULL REFERENCES Dealers(dealer_id),
    submitted_date        TEXT NOT NULL,
    repair_date           TEXT NOT NULL,
    operation_code        TEXT NOT NULL,
    claimed_part          TEXT,
    claimed_labour_hours  REAL NOT NULL,
    goodwill_requested    REAL,
    status                TEXT NOT NULL
);

CREATE TABLE ServiceHistory (
    job_id          TEXT PRIMARY KEY,
    serial          TEXT NOT NULL REFERENCES Assets(serial),
    job_date        TEXT NOT NULL,
    operation_code  TEXT NOT NULL,
    component       TEXT,
    part_fitted     TEXT,
    labour_hours    REAL,
    claim_id        TEXT,
    completed_date  TEXT
);

CREATE TABLE GoodwillAuthority (
    tier            INTEGER PRIMARY KEY,
    max_amount_inr  REAL,
    approver_role   TEXT NOT NULL
);

-- Reporting table. Maintained by hand and known to lag the bulletin documents.
-- Policy 1.4: where this table and a bulletin disagree, the bulletin governs.
CREATE TABLE TsbApplicability (
    tsb_id          TEXT PRIMARY KEY,
    family          TEXT NOT NULL,
    serial_from     INTEGER,
    serial_to       INTEGER,
    effective_from  TEXT,
    status          TEXT
);

-- Action tables. Everything the agent writes is a draft; nothing pays or sends.
CREATE TABLE ClaimAdjudicationDraft (
    draft_id          TEXT PRIMARY KEY,
    claim_id          TEXT NOT NULL,
    decision          TEXT NOT NULL,
    payable           REAL,
    currency          TEXT,
    instrument_refs   TEXT,
    notes             TEXT,
    created_at        TEXT NOT NULL,
    created_by        TEXT
);

CREATE TABLE EvidenceRequest (
    request_id   TEXT PRIMARY KEY,
    claim_id     TEXT NOT NULL,
    field_name   TEXT NOT NULL,
    reason       TEXT,
    created_at   TEXT NOT NULL
);

CREATE TABLE GoodwillEscalation (
    escalation_id  TEXT PRIMARY KEY,
    claim_id       TEXT NOT NULL,
    amount         REAL NOT NULL,
    approver_role  TEXT NOT NULL,
    created_at     TEXT NOT NULL,
    status         TEXT NOT NULL
);

CREATE INDEX idx_telemetry_serial ON AssetTelemetry(serial, as_of_date);
CREATE INDEX idx_history_serial   ON ServiceHistory(serial, job_date);
CREATE INDEX idx_claims_serial    ON Claims(serial);
